with i as (select order_id,count(*) line_count,sum(quantity) item_quantity,sum(quantity*unit_price) gross_item_amount,sum(discount) item_discount_amount from {{ ref('stg_order_items') }} group by order_id), p as (select order_id,sum(amount) payment_amount,max(transaction_timestamp) last_payment_timestamp from {{ ref('stg_payments') }} group by order_id) select o.order_id,o.customer_id,cast(date_format(cast(o.order_date as date),'yyyyMMdd') as int) date_key,o.order_date,o.order_status,o.payment_method,o.shipping_country,o.shipping_state,o.total_amount,o.discount order_discount,o.tax,coalesce(i.line_count,0) line_count,coalesce(i.item_quantity,0) item_quantity,coalesce(i.gross_item_amount,0) gross_item_amount,coalesce(i.item_discount_amount,0) item_discount_amount,coalesce(p.payment_amount,0) payment_amount,p.last_payment_timestamp,cast(coalesce(p.payment_amount,0)-coalesce(o.total_amount,0) as decimal(18,2)) payment_variance,case when p.payment_amount is null then 'NO_PAYMENT' when abs(p.payment_amount-o.total_amount)<=0.01 then 'MATCHED' else 'MISMATCH' end payment_match_status,o.created_at,o.updated_at from {{ ref('stg_orders') }} o left join i on o.order_id=i.order_id left join p on o.order_id=p.order_id
